INSERT INTO `products` VALUES
(1,'BIM ACCÈS : 200$/AN',200.00,'Est un package individuel valable une année.\nIl prend en charge les maladies courantes : Paludisme, fièvre Typhoïde, grippe, blessures, brûlures, fractures légère.\nServices offerts : Fiche de consultation, soins infirmiers, examens de laboratoire liés aux pathologies prises en charge, médicaments génériques, hospitalisation à 50%.',0.00,NULL,1,0,'2026-12-31 00:00:00',NULL,'/images/1772569042795-202714109.jpeg',1,NULL,NULL,'2026-02-12 09:23:45','2026-05-10 16:02:02',NULL,8,'Package',0),
(2,'BIM FAMILY : 400$/AN',400.00,'Est un package familial valable également une année, qui comprend 4 personnes, papa, maman et deux enfants.\nIl prend en charge les maladies courantes : Paludisme, fièvre typhoïde, grippe, blessures, brûlures, fractures légère.\nServices offerts : Fiche de consultation, soins infirmiers, examens de laboratoire liés aux pathologies prises en charge, médicaments génériques, hospitalisation à 50%.',0.00,NULL,4,0,'2026-12-31 00:00:00',NULL,'/images/1772569127338-339257304.jpeg',1,NULL,NULL,'2026-02-12 09:23:45','2026-05-10 16:02:22',NULL,8,'Package',0),
(3,'BIM FULL FAMILY : 1000$/AN',1000.00,'Est un package pour une grande famille composé de 10 personnes valable une année.\nIl prend en charge les maladies courantes : Paludisme, fièvre typhoïde, grippe, blessures, brûlures, fractures légère.\nServices offerts : Fiche de consultation, soins infirmiers, examens de laboratoire liés aux pathologies prises en charge, médicaments génériques, hospitalisation à 50%.',NULL,NULL,10,NULL,'2026-12-31 00:00:00',NULL,'/images/1772569210515-140517035.jpeg',1,NULL,NULL,'2026-02-12 09:23:45','2026-03-03 20:20:10',NULL,8,'Package',NULL),
